<section {...owned('structured-list','root',!p.items.length&&'empty')} data-krds-variant={p.variant??'list'}><div {...owned('structured-list','toolbar')}>{#if p.toolbarContent}{@render p.toolbarContent()}{:else}{#each p.toolbar??[] as action(action.id)}<button type="button" disabled={action.disabled} onclick={()=>p.onToolbarAction?.({id:action.id})}>{action.label}</button>{/each}{#if p.sort}<button type="button" onclick={()=>p.sort?.onChange({key:p.sort.key,direction:p.sort.direction==='ascending'?'descending':'ascending'})}>정렬 {p.sort.direction==='ascending'?'오름차순':'내림차순'}</button>{/if}{/if}</div>{#snippet content(item:import('@unofficial-krds/contracts').StructuredListItem)}{#if item.image}<img {...owned('structured-list','preview')} src={item.image.src} alt={item.image.alt}/>{/if}<div {...owned('structured-list','content')}><h3>{#if item.href}<a {...owned('structured-list','cta')} href={item.href}>{item.title}</a>{:else}{item.title}{/if}</h3><dl {...owned('structured-list','metadata')}>{#each item.metadata as field}<div><dt>{field.label}</dt><dd>{field.value??'—'}</dd></div>{/each}</dl><div {...owned('structured-list','tags')}>{#each item.tags??[] as tag}<span>{tag}</span>{/each}</div></div>{#if p.selection}<input type="checkbox" data-selection-id={item.id} aria-label={`${item.title} 선택`} checked={p.selection.ids.includes(item.id)} onchange={event=>{const node=event.currentTarget;p.selection?.onChange({ids:p.selection.ids.includes(item.id)?p.selection.ids.filter(x=>x!==item.id):[...p.selection.ids,item.id]});void tick().then(()=>{if(node.isConnected)node.checked=p.selection?.ids.includes(item.id)??false;});}}/>{/if}{#if p.actions}<div {...owned('structured-list','actions')}>{@render p.actions(item)}</div>{/if}{/snippet}{#if p.variant==='table'}<table {...owned('structured-list','list')}><caption>목록</caption><thead><tr><th scope="col">항목</th></tr></thead><tbody>{#each p.items as item(item.id)}<tr id={item.id} {...owned('structured-list','item')}><td>{@render conte